// Change orders and Drawings view models against the prototype's own render values (eco.golden.json, generated by
// scripts/proto-golden-eco.ts from design lines 3096–5239, renderValsEN and renderVals in French) on the seeded
// in-memory database — the ECOs read through the Vigie connector (mock over the seeded mirror), the drawings from the
// PDM vault mirror — in EN and FR, for every persona: KPI tiles, chips, rows, the ECO drawer, the drawings register
// and drawer, and the template labels. Deliberate deviations are listed in DEVIATIONS and asserted explicitly.
import { beforeAll, describe, expect, it } from 'vitest';
import { PERSONA_BY_ROLE } from '@/config/personas';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import { getDrawingsScreen, getEcoDrawer, getEcoScreen } from '@/server/dal/eco-screen';
import { getApproverIdentity } from '@/server/dal/myapprovals-identity';
import GOLD from './eco.golden.json';
import { drawingDrawerView, drawingsView } from './drawings/model';
import { ecoDrawerView, ecoScreenView, type EcoState } from './model';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const LANGS: Lang[] = ['en', 'fr'];
const ROLES = ['director', 'pm', 'depthead', 'member', 'englead', 'quality', 'procurement', 'client'] as const;
const S0: EcoState = { status: null, eco: null };

/**
 * Deliberate deviations from the prototype's French (exact-match translation of data from Vigie; translated persona
 * title; French day unit, as My approvals and Change control). Applied to the golden values before comparing.
 */
const DEVIATIONS: [string, string][] = [
  ['Aucun — not yet ordered', 'None — not yet ordered'],
  ['En tant que Project manager', 'En tant que Chef de projet'],
  ['En tant que Engineering lead', 'En tant que Référent ingénierie'],
  ['En tant que Quality manager', 'En tant que Responsable qualité'],
  ['-6 d', '-6 j'],
];
const fix = (lang: Lang, s: string) => (lang === 'fr' ? DEVIATIONS.reduce((x, [a, b]) => (x === a ? b : x), s) : s);
/** Zero-padded prototype dates ("03 Jul") are written "3 Jul" (as the Delivery 4 data layer). */
const day = (s: string) => s.replace(/(^|· )0(\d)/g, '$1$2');

/**
 * A-12 (chapter 4): "Released this month" keeps the released ECOs of the data date's month (09 OQ18) — ECO-2026-014
 * (raised 12 Sep, Vigie reports no approval date), not ECO-2026-012 (raised 28 Aug): 1 · €9,400 instead of 2 · €10,360.
 */
const releasedThisMonth = (k: any) => ({ ...k, value: 1, sub: k.sub.replace('10,360', '9,400').replace(/10\s360/, (m: string) => `9${m.slice(2, 3)}400`) });

beforeAll(async () => {
  setDb(await openDatabase());
}, 60_000);

async function screen(role: (typeof ROLES)[number], lang: Lang, state: EcoState = S0) {
  const viewer = PERSONA_BY_ROLE[role];
  const data = await getEcoScreen(viewer, state.eco);
  return ecoScreenView({ ecos: data.ecos, awaitingMine: data.awaitingMine, state, viewer }, makeT(lang), lang);
}

async function drawer(role: (typeof ROLES)[number], lang: Lang, number: string) {
  const viewer = PERSONA_BY_ROLE[role];
  const [data, identity] = await Promise.all([getEcoDrawer(number), getApproverIdentity(viewer)]);
  return ecoDrawerView({ data: data!, state: { status: null, eco: number }, viewer: { role, managedProjects: identity.managedProjects } }, makeT(lang), lang);
}

describe('Change orders register — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles for every persona', async (lang) => {
    for (const role of ROLES) {
      const v = await screen(role, lang);
      expect(v.kpis.map((k) => ({ label: k.label, value: Number(k.value), sub: k.sub, color: k.color })), role)
        .toEqual(G[lang].eco.byRole[role].kpis.map((k: any, i: number) => (i === 2 ? releasedThisMonth(k) : { ...k, sub: fix(lang, k.sub) })));
    }
  });

  it.each(LANGS)('%s: chips (links), rows and selection', async (lang) => {
    const v = await screen('director', lang);
    expect(v.chips.map((c) => ({ label: c.label, count: String(c.count) }))).toEqual(G[lang].eco.chips);
    expect(v.chips.map((c) => c.href)).toEqual(['/reference/eco', ...['draft', 'impact_analysis', 'in_approval', 'released', 'rejected'].map((s) => `/reference/eco?status=${s}`)]);
    const g = G[lang].eco.rows;
    expect(v.rows.map((r) => ({
      id: r.number, title: r.title, type: r.type, status: r.status, tagClass: r.statusClass, parts: r.parts, projects: r.projects, byLine: r.byLine, cost: r.cost, sched: r.sched,
      pend: r.pending?.text ?? null, lock: r.pending?.lock ?? false, approvals: r.approvals.map((a) => ({ label: a.label, dot: a.dot })),
      action: r.action ? (r.action.kind === 'tag' ? `tag:${r.action.label}` : `${r.action.variant}:${r.action.label}`) : null,
    }))).toEqual(g.map((r: any) => ({
      id: r.id, title: r.title, type: r.type, status: r.status, tagClass: r.tagClass, parts: r.parts, projects: r.projects, byLine: `${r.by} · ${r.date}`, cost: r.cost, sched: fix(lang, r.sched),
      pend: r.hasPend ? r.pendText : null, lock: r.lockIcon === 'ph ph-lock-simple', approvals: r.approvals,
      action: r.canStart ? `secondary:${lang === 'fr' ? 'Lancer l’analyse d’impact' : 'Start impact analysis'}` : r.canSubmit ? 'primary:Submit for approval'
        : r.needInterch ? `tag:${lang === 'fr' ? 'Définir l’interchangeabilité' : 'Set interchangeability'}` : null,
    })));
    expect(v.rows.every((r) => r.sync === null && r.vigieUrl === `http://localhost:3200/modifications-techniques/${r.number}`)).toBe(true);
    expect(v.empty).toBeNull();
    // Row links toggle the drawer and keep the filter.
    const sel = await screen('director', lang, { status: 'in_approval', eco: 'ECO-2026-015' });
    expect(sel.rows.map((r) => [r.number, r.selected, r.href])).toEqual([['ECO-2026-015', true, '/reference/eco?status=in_approval']]);
    expect(sel.chips[0].href).toBe('/reference/eco?eco=ECO-2026-015');
    expect(G[lang].eco.selectedIdColor).toEqual(v.rows.map((r) => (r.number === 'ECO-2026-015' ? 'var(--color-accent-300)' : 'var(--color-neutral-300)')));
  });

  it.each(LANGS)('%s: status filter rows and the empty state', async (lang) => {
    const codes: Record<string, EcoState['status']> = { Draft: 'draft', 'Impact analysis': 'impact_analysis', 'In approval': 'in_approval', Released: 'released', Rejected: 'rejected' };
    for (const [label, status] of Object.entries(codes)) {
      expect((await screen('pm', lang, { status, eco: null })).rows.map((r) => r.number)).toEqual(G[lang].eco.filters[label].rows);
    }
    const none = ecoScreenView({ ecos: [], awaitingMine: 0, state: S0, viewer: PERSONA_BY_ROLE.pm }, makeT(lang), lang);
    expect(none.empty).toBe(lang === 'fr' ? 'Aucun ECO dans ce statut' : 'No ECO in this status');
  });
});

describe('ECO drawer — EN and FR, every persona of the screen', () => {
  const NUMBERS = ['ECO-2026-014', 'ECO-2026-015', 'ECO-2026-016', 'ECO-2026-017', 'ECO-2026-012', 'ECO-2026-011'];
  it.each(LANGS)('%s', async (lang) => {
    for (const role of ['director', 'pm', 'englead', 'quality', 'procurement'] as const) {
      for (const n of NUMBERS) {
        const d = await drawer(role, lang, n);
        const g = G[lang].eco.drawers[n][role];
        const tag = `${role} ${n}`;
        expect([d.number, d.title, d.type, d.status, d.statusClass, d.closeHref], tag).toEqual([g.id, g.title, g.type, g.status, g.tagClass, '/reference/eco']);
        expect(d.raisedBy, tag).toBe(`${lang === 'fr' ? 'Émise par' : 'Raised by'} ${g.by}`);
        expect(d.steps.map((s) => ({ label: s.label, dot: s.reached && !d.rejected ? 'var(--color-accent)' : 'var(--color-neutral-700)' })), tag).toEqual(g.steps.map((s: any) => ({ label: s.label, dot: s.dot })));
        expect(d.impact, tag).toEqual(g.impact.map((x: any) => ({ ...x, v: fix(lang, x.v) })));
        expect(d.parts.map((p) => ({ ref: p.ref, name: p.name, status: p.status, tagClass: p.statusClass })), tag).toEqual(g.parts);
        expect(d.parts.every((p) => p.href === `/reference/parts?part=${p.ref}`)).toBe(true);
        expect([d.revText, d.pending.text, d.pending.tagClass, d.locked], tag).toEqual([g.revText, g.pendText, g.pendTag, g.isLocked]);
        expect([d.interch.label, d.interch.tagClass, d.interch.hint, d.interch.manage], tag).toEqual([g.interchLabel, g.interchTag, g.interchHint, g.canSetInterch]);
        const proj = lang === 'fr' ? 'Projets et nomenclatures' : 'Projects & BOMs';
        const inst = lang === 'fr' ? 'Parc installé' : 'Installed base';
        expect([d.projectsTitle, d.machinesTitle], tag).toEqual([`${proj} · ${g.projCount}`, `${inst} · ${g.mchCount}`]);
        const decided = lang === 'fr' ? 'Décidé par' : 'Decided by';
        const target = (t: any) => ({ name: t.name, sub: `${t.sub} · ${t.l1} · ${t.l2} · ${t.l3}`, revText: t.revText, label: t.label, tagClass: t.tagClass, decidedBy: `${decided} ${t.decider}${t.hasNote ? ` · ${t.note}` : ''}`, manage: t.canDecide });
        const mine = (t: any) => ({ name: t.name, sub: t.sub, revText: t.revText, label: t.label, tagClass: t.tagClass, decidedBy: t.decidedBy, manage: t.manage });
        expect(d.projects.map(mine), tag).toEqual(g.dispProjects.map(target));
        expect(d.machines.map(mine), tag).toEqual(g.dispMachines.map(target));
        expect(d.projects.every((x) => x.href === `/projects/${x.key}/bom`) && d.machines.every((x) => x.href === '/after-sales/fleet')).toBe(true);
        expect(d.noMachines === null, tag).toBe(!g.noMachines);
        expect(!!d.retrofit, tag).toBe(g.hasRetrofit);
        expect(d.pinned ?? '', tag).toBe(g.hasPinned ? `${lang === 'fr' ? 'Les révisions épinglées conservent leurs pièces de rechange et leur stock — ne pas rebuter :' : 'Pinned revisions keep their spare parts and stock — do not scrap:'} ${g.pinnedList}` : '');
        expect(d.approvals.map((a) => ({ label: a.label, who: a.who, state: a.state, tagClass: a.tagClass, canAct: a.canAct })), tag).toEqual(g.approvers);
        expect(d.approvals.every((a) => a.sync === null)).toBe(true);
        expect(d.hint, tag).toBe(g.roleHint);
        expect([d.vigieUrl, d.sync]).toEqual([`http://localhost:3200/modifications-techniques/${n}`, null]);
      }
    }
  });
});

describe('Drawings — PDM vault — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles, chips, rows, search and the drawer', async (lang) => {
    const t = makeT(lang);
    const data = await getDrawingsScreen(null);
    const v = drawingsView({ drawings: data.drawings, sync: data.sync, state: { state: null, q: '', dwg: null } }, t);
    const g = G[lang].drawings;
    // A-12 (chapter 4): the "Last vault sync" day is computed from the run against the data date (25 Sep). The latest run
    // is the PDM connector row's, seeded "26 Sep 07:40" from the prototype's CONNECTORS — the prototype printed "today".
    const lastSync = lang === 'fr' ? 'SolidWorks PDM · 26 sept. · lecture seule' : 'SolidWorks PDM · 26 Sep · read-only';
    expect(v.kpis.map((k) => ({ label: k.label, value: k.value, sub: k.sub, color: k.color })))
      .toEqual(g.kpis.map((k: any, i: number) => ({ ...k, value: String(k.value), ...(i === 4 ? { sub: lastSync } : {}) })));
    expect(v.chips.map((c) => ({ label: c.label, count: String(c.count) }))).toEqual(g.chips);
    expect(v.rows.map((r) => ({ no: r.number, title: r.title, part: r.part, partName: r.partName, rev: r.rev, state: r.state, tagClass: r.stateClass, path: r.path, byLine: r.byLine, eco: r.eco })))
      .toEqual(g.rows.map((r: any) => ({ no: r.no, title: r.title, part: r.part, partName: r.partName, rev: r.rev, state: r.state, tagClass: r.tagClass, path: r.path, byLine: day(`${r.by} · ${r.date}`), eco: r.eco })));
    for (const [q, ids] of Object.entries(g.search as Record<string, string[]>)) {
      const s = drawingsView({ drawings: data.drawings, sync: data.sync, state: { state: null, q, dwg: null } }, t);
      expect(s.rows.map((r) => r.number), q).toEqual(ids);
      expect(s.empty).toBe(ids.length ? null : lang === 'fr' ? 'Aucun plan ne correspond' : 'No drawing matches');
    }
    for (const r of data.drawings) {
      const det = (await getDrawingsScreen(r.number)).detail!;
      const d = drawingDrawerView({ drawing: det, state: { state: 'released', q: 'rmg', dwg: r.number } }, t);
      const gd = g.drawers[r.number];
      expect([d.head, d.title, d.state, d.stateClass, d.closeHref]).toEqual([`${gd.no} ${lang === 'fr' ? '· rév.' : '· rev'} ${gd.rev}`, gd.title, gd.state, gd.tagClass, '/reference/drawings?state=released&q=rmg']);
      expect(d.meta).toEqual(gd.meta.map((m: any) => ({ k: m.k, v: day(m.v) })));
      expect(d.history).toEqual(gd.hist.map((h: any) => ({ ...h, label: day(h.label) })));
      expect([!!d.ecoHref, d.partHref]).toEqual([gd.hasEco, `/reference/parts?part=${r.partRef}`]);
      if (d.ecoHref) expect(d.ecoHref).toBe(`/reference/eco?eco=${r.ecoNumber}`);
    }
    // "Open in PDM" opens a new window: only an http(s) link from the PDM sync is kept.
    const det = (await getDrawingsScreen('DWG-AS-9000')).detail!;
    const pdm = (u: string) => drawingDrawerView({ drawing: { ...det, pdmUrl: u }, state: { state: null, q: '', dwg: det.number } }, t).pdmUrl;
    expect([pdm('https://pdm.example/DWG-AS-9000'), pdm('javascript:alert(1)'), pdm('')]).toEqual(['https://pdm.example/DWG-AS-9000', null, null]);
  });
});

describe('template labels', () => {
  it('every label of the two screens translates as in the prototype', () => {
    const t = makeT('fr');
    for (const [en, fr] of Object.entries({ ...G.labels, ...G.extra } as Record<string, string>)) {
      expect(t(en), en).toBe(fr);
    }
  });
});
